/* @lc app=leetcode id=4035 lang=kotlin */ class Solution { fun g(a: Int, b: Int): Int = if (b == 0) a else g(b, a % b) fun cnt(a: List<Int>): Int = a.size.let { m -> a.runningFold(0) { x, y -> g(x, y) }.let { pre -> a.reversed().runningFold(0) { x, y -> g(x, y) }.reversed().let { suf -> (0 until m - 1).count { pre[it + 1] == suf[it + 1] } } } } fun maxValidSplits(nums: IntArray): Int = (listOf(-1) + nums.indices).maxOf { r -> cnt(nums.filterIndexed { i, _ -> i != r }) } }